import{_ as a,o as t,c as i,a0 as l}from"./chunks/framework.B4x6lK7E.js";const p=JSON.parse('{"title":"NetGet Package Surface","description":"","frontmatter":{},"headers":[],"relativePath":"Packaging.md","filePath":"Packaging.md"}'),o={name:"Packaging.md"};function c(s,e,r,d,n,u){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="netget-package-surface" tabindex="-1">NetGet Package Surface <a class="header-anchor" href="#netget-package-surface" aria-label="Permalink to &quot;NetGet Package Surface&quot;">​</a></h1><p><code>netget</code> is the gateway CLI/runtime package. It should publish only the files needed to install, run and configure the local gateway.</p><h2 id="published-files" tabindex="-1">Published Files <a class="header-anchor" href="#published-files" aria-label="Permalink to &quot;Published Files&quot;">​</a></h2><ul><li><code>bin/</code>: the executable wrapper used by <code>npx netget</code>.</li><li><code>dist/</code>: public library exports.</li><li><code>src/</code>: TypeScript runtime and CLI sources while the executable still runs through <code>tsx</code>.</li><li><code>src/modules/NetGetX/OpenResty/lua/</code>: Lua handlers installed into OpenResty.</li><li><code>src/htmls/*.html</code>: small legacy HTML templates still used by setup flows.</li><li><code>assets/main-server-ui/dist/</code>: the bundled NetGet admin UI.</li></ul><h2 id="explicitly-not-published" tabindex="-1">Explicitly Not Published <a class="header-anchor" href="#explicitly-not-published" aria-label="Permalink to &quot;Explicitly Not Published&quot;">​</a></h2><ul><li><code>main-server/</code>: legacy prebuilt React UI with large media assets.</li><li><code>src/htmls/Netget-REACT/</code>: old React source/build tree.</li><li><code>gui/</code>: the component-library workspace, published separately as <code>netget.gui</code>.</li><li><code>docs/.vitepress/cache/</code>: generated docs cache.</li><li><code>tests/</code>: repository validation only.</li></ul><h2 id="current-compromise" tabindex="-1">Current Compromise <a class="header-anchor" href="#current-compromise" aria-label="Permalink to &quot;Current Compromise&quot;">​</a></h2><p>The CLI still runs <code>src/netget.cli.ts</code> with <code>tsx</code>, so the package must include selected TypeScript sources for now. The next packaging improvement is to compile the CLI and its runtime graph into <code>dist/</code>, then remove <code>src/</code> from the published package entirely.</p><h2 id="guardrail" tabindex="-1">Guardrail <a class="header-anchor" href="#guardrail" aria-label="Permalink to &quot;Guardrail&quot;">​</a></h2><p><code>tests/package-surface.test.ts</code> checks that the allowlist stays narrow. Always run <code>npm pack --dry-run</code> before publishing; the package should stay small and must not include old UI trees, nested <code>node_modules</code>, media dumps or docs cache.</p>',10)])])}const m=a(o,[["render",c]]);export{p as __pageData,m as default};
